{"ideviceId":"idevice-1792777859345-cmdk0m0sy","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<div id="gauss-tutor-wrapper" style="font-family: 'Segoe UI', Arial, sans-serif; width: 100%; color: #333; box-sizing: border-box;">
<h2 style="color: #d35400; text-align: center; border-bottom: 3px solid #f39c12; padding-bottom: 10px; margin-top: 0;">Tutor Interactivo: Inversa por Gauss-Jordan</h2>
