<style>
    #gauss-tutor-wrapper .action-btn { background-color: #e67e22 !important; color: white !important; border: none !important; border-radius: 5px !important; cursor: pointer !important; font-weight: bold !important; padding: 10px 20px !important; font-size: 1.1em !important; transition: filter 0.3s !important; }
    #gauss-tutor-wrapper .action-btn-dark { background-color: #d35400 !important; color: white !important; border: none !important; border-radius: 4px !important; cursor: pointer !important; font-weight: bold !important; padding: 6px 15px !important; margin: 0 5px !important; }
    #gauss-tutor-wrapper .action-btn-alt { background-color: #7f8c8d !important; color: white !important; border: none !important; border-radius: 4px !important; cursor: pointer !important; font-weight: bold !important; padding: 6px 15px !important; margin: 0 5px !important; }
    #gauss-tutor-wrapper button:hover { filter: brightness(0.9) !important; }
    #gauss-tutor-wrapper button:disabled { background-color: #f9f9f9 !important; border: 1px solid #ccc !important; color: #aaa !important; cursor: not-allowed !important; }

    #gauss-tutor-wrapper .inv-paso-box { background: #fff !important; border: 1px solid #ffe0b2 !important; border-left: 5px solid #f57c00 !important; border-radius: 6px !important; padding: 15px !important; margin-bottom: 15px !important; box-shadow: 0 2px 5px rgba(0,0,0,0.05) !important; }

    #gauss-tutor-wrapper .inv-input-coef { width: 55px !important; padding: 5px !important; text-align: center !important; border: 1px solid #aaa !important; border-radius: 4px !important; font-weight: bold !important; background-color: #fff !important; color: #333 !important; }
    #gauss-tutor-wrapper .inv-input-val { width: 55px !important; padding: 5px !important; text-align: center !important; border: 1px solid #aaa !important; border-radius: 4px !important; background-color: #fff !important; color: #333 !important; }
    #gauss-tutor-wrapper .inv-input-val:focus, #gauss-tutor-wrapper .inv-input-coef:focus { outline: none !important; border-color: #f57c00 !important; background-color: #fff3e0 !important; box-shadow: 0 0 5px rgba(245, 124, 0, 0.3) !important; }

    #gauss-tutor-wrapper .inv-feedback { font-weight: bold !important; margin-left: 10px !important; font-size: 0.9em !important; }
    #gauss-tutor-wrapper .inv-success { color: #28a745 !important; }
    #gauss-tutor-wrapper .inv-error { color: #dc3545 !important; }

